import java.util.stream.*;
import java.util.*;

List<String> spells = Arrays.asList("Fire","Ice","Fog","Flash","Force");

// Join
String joined = spells.stream().collect(Collectors.joining(", "));
System.out.println(joined); // Fire, Ice, Fog, Flash, Force

// Group by first letter
Map<Character,List<String>> groups = spells.stream()
    .collect(Collectors.groupingBy(s -> s.charAt(0)));
System.out.println(groups.get('F')); // [Fire, Fog, Flash, Force]

